+}
+
+func TestEngineApplyActionDouble(t *testing.T) {
+	shoe := newTestShoe()
+	engine := NewEngineWithShoe(DefaultRules(), 1000, shoe)
+	engine.StartRound(10)
+
+	before := engine.Bankroll
