	}
	if Outcome(99).String() != "Outcome(99)" {
		t.Errorf("unexpected default Outcome string")
	}
}

func TestHandTotalEmpty(t *testing.T) {
	h := NewHand(10)
	hard, soft, isSoft := h.Total()
	if hard != 0 || soft != 0 || isSoft {
