func upcardIndex(c deck.Card) int {
	switch {
	case c.Rank >= deck.Two && c.Rank <= deck.Nine:
		return int(c.Rank) - 2
	case c.Rank == deck.Ten || c.Rank == deck.Jack || c.Rank == deck.Queen || c.Rank == deck.King:
		return 8
	case c.Rank == deck.Ace:
		return 9
	default:
		return 0
	}
}

