+	}
+
+	// Quit test
+	qReader := bufio.NewReader(strings.NewReader("q\n"))
+	var qOut bytes.Buffer
+	_, qOk := ui.PromptBet(qReader, &qOut, 10, 500, 1000)
+	if qOk {
+		t.Errorf("expected ok=false on quit")
+	}
